                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.ANAM:
                {
                    item.CameraPaths = Mutagen.Bethesda.Fallout76.CameraPathData.CreateFromBinary(frame: frame);
                    return (int)CameraPath_FieldIndex.CameraPaths;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    item.Conditions = 
